def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        if resource.kind not in app.observer_schemas:
            app.observer_schemas[resource.kind] = {
                "kind": resource.kind,
                "apiVersion": resource.apiVersion,
                "metadata": {
                    "name": resource.metadata.name,
                    "namespace": resource.metadata.namespace,
                    "labels": resource.metadata.labels,
                    "annotations": resource.metadata.annotations,
                },
                "spec": {
                    "selector": {
                        "matchLabels": resource.spec.selector.matchLabels,
                    },
                    "template": {
                        "metadata": {
                            "labels": resource.spec.template.metadata.labels,
                            "annotations": resource.spec.template.metadata.annotations,
                        },
                        "spec": {
                            "containers": [
                                {
                                    "name": resource.spec.template.spec.containers[0].name,
                                    "image": resource.spec.template.spec.containers[0].image,
                                    "ports": resource.spec.template.spec.containers[0].ports,
                                    "env": resource.spec.template.spec.containers[0].env,
                                }
                            ],
                            "volumes": resource.spec.template.spec.volumes,
                        },
                    },
                },
            }
    return app.observer_schemas

