    try:
        with open(VERSION_PATH, 'r') as rfile:
            contents = rfile.read().strip()

        _, version = contents.split('=')
        version = version.strip()

        # Remove quotes
        return version.strip('"\'')
    except:
        return "default"

def render(pieces, style):
    """Render the given version pieces into the requested style."""

    # Initialize an empty list to store the rendered pieces
    rendered_pieces = []

    # Iterate over the given version pieces
    for piece in pieces:
        # Check if the piece is a string
        if isinstance(piece, str):
            # If it is a string, add it to the rendered pieces list
            rendered_pieces.append(piece)
        # If the piece is not a string, check if it is a list
        elif isinstance(piece, list):
            # If it is a list, render it recursively and add the result to the rendered pieces list
            rendered_pieces.append(render(piece, style))
        # If the piece is not a string or a list, raise an error
        else:
            raise ValueError("Invalid piece type: %s" % type(piece))

    # Join the rendered pieces into a single string using the requested style
    return style.join(rendered_pieces)

