    return " ".join(flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = []
    for subparser_name, subparser in subparsers.items():
        try:
            parsed_args[subparser_name] = subparser.parse_args(unparsed_arguments)
            unparsed_arguments = []
        except SystemExit:
            remaining_args = unparsed_arguments
    return parsed_args, remaining_args

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    units = {"B": 1, "K": 1000, "M": 1000000, "G": 1000000000, "T": 1000000000000, "P": 1000000000000000, "E": 1000000000000000000, "Z": 1000000000000000000000, "Y": 1000000000000000000000000}
    if size[-1] in units:
        return int(float(size[:-1]) * units[size[-1]])
    else:
        return int(size)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """

    result = {}
    for d in dicts:
        for k, v in d.items():
            if k not in result:
                result[k] = v
            else:
                result[k] += v
    return result

