def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    match = re.match(r"^(\d+) (\w+)$", frequency)
    if not match:
        raise ValueError("Invalid frequency string")
    num, unit = match.groups()
    if unit == "weeks":
        return datetime.timedelta(weeks=int(num))
    elif unit == "days":
        return datetime.timedelta(days=int(num))
    elif unit == "hours":
        return datetime.timedelta(hours=int(num))
    elif unit == "minutes":
        return datetime.timedelta(minutes=int(num))
    elif unit == "seconds":
        return datetime.timedelta(seconds=int(num))
    else:
        raise ValueError("Invalid unit of time")

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    """
    config_path = os.path.expanduser(config_filename)
    if not overwrite and os.path.isfile(config_path):
        return
    else:
        try:
            config_path_dir_name = os.path.dirname(config_path)
            os.makedirs(config_path_dir_name)
        except OSError:
            if not os.path.isdir(config_path_dir_name):
                raise
        with open(config_path, "w", mode) as f:
            f.write(rendered_config)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    if isinstance(args, str):
        args = [args]
    if cwd is None:
        cwd = os.getcwd()
    if env is None:
        env = os.environ
    if verbose:
        print("Running command: {}".format(" ".join(commands + args)))
    try:
        output = subprocess.check_output(commands + args, cwd=cwd, stderr=subprocess.STDOUT if hide_stderr else None, env=env)
    except subprocess.CalledProcessError as e:
        raise ProgramError("Command failed with exit code {}: {}".format(e.returncode, " ".join(commands + args)))
    return output.decode("utf-8").strip()

