            return base.__metaclass__
    return type

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)
    return self._redis.delete(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Find the least frequently used key-value pair
    least_frequent_key = None
    least_frequent_value = None
    for key, value in self.items():
        if least_frequent_key is None or self.get_frequency(key) < self.get_frequency(least_frequent_key):
            least_frequent_key = key
            least_frequent_value = value
    # Remove the least frequently used key-value pair
    self.pop(least_frequent_key)
    return (least_frequent_key, least_frequent_value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if self.is_empty():
        raise KeyError("list is empty")
    else:
        key = self._head[2]
        value = self._head[3]
        self._head = self._head[1]
        self._size -= 1
        return (key, value)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if len(self) == 0:
        raise KeyError("list is empty")
    else:
        key = random.choice(list(self.keys()))
        value = self.pop(key)
        return (key, value)

