def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")

    with open(yaml_file, 'r') as f:
        data = yaml.load(f)

    if not data:
        raise IRValidatorException("YAML file is empty")

    if 'name' not in data:
        raise IRValidatorException("'name' field is missing in YAML file")

    if 'description' not in data:
        raise IRValidatorException("'description' field is missing in YAML file")

    if 'type' not in data:
        raise IRValidatorException("'type' field is missing in YAML file")

    if 'version' not in data:
        raise IRValidatorException("'version' field is missing in YAML file")

    if 'author' not in data:
        raise IRValidatorException("'author' field is missing in YAML file")

    if 'license' not in data:
        raise IRValidatorException("'license' field is missing in YAML file")

    if 'source' not in data:
        raise IRValidatorException("'source' field is missing in YAML file")

    if 'requirements' not in data:
        raise IRValidatorException("'requirements' field is missing in YAML file")

    if 'dependencies' not in data:
        raise IRValidatorException("'dependencies' field is missing in YAML file")

    if 'dev_dependencies' not in data:
        raise IRValidatorException("'dev_dependencies' field is missing in YAML file")

    if 'scripts' not in data:
        raise IRValidatorException("'scripts' field is missing in YAML file")

    if 'config' not in data:
        raise IRValidatorException("'config' field is missing in YAML file")

    if 'data' not in data:
        raise IRValidatorException("'data' field is missing in YAML file")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    include_groups = parser_dict.get('include_groups', [])
    for group in include_groups:
        group_name = group['name']
        group_options = group['options']
        if group_name not in self.groups:
            self.groups[group_name] = []
        self.groups[group_name].extend(group_options)
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to build default for non-Option type')

        # if there is a default set, add it to the spec_defaults dict
        if not isinstance(arg.default, NoDefault):
            spec_defaults[arg.name] = arg.default

        # if we have a dict option, build the spec_defaults for its scheme.
        # if any spec_defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                b = arg.scheme.build_spec_defaults()
                if b:
                    spec_defaults[arg.name] = b
    return spec_defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """

    deprecated_args = {}

    # Add deprecated arguments here
    deprecated_args["old_arg"] = "new_arg"

    return deprecated_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_args = self.get_deprecated_args()
    for arg in deprecated_args:
        if arg in cli_args:
            print(f"Warning: argument '{arg}' is deprecated and will be removed in a future version. Please use '{deprecated_args[arg]}' instead.")
        if arg in answer_file_args:
            print(f"Warning: argument '{arg}' is deprecated and will be removed in a future version. Please use '{deprecated_args[arg]}' instead.")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    option_spec = self.option_specs.get(command_name)
    if option_spec is None:
        raise ValueError("Invalid command name: {}".format(command_name))
    argument_spec = option_spec.get(argument_name)
    if argument_spec is None:
        raise ValueError("Invalid argument name: {}".format(argument_name))
    return argument_spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_args = []
    for arg in args:
        if arg.startswith('-') and arg not in ['-h', '--help']:
            silent_args.append(arg)
    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    for arg in self.args:
        if arg.required and arg.name not in args:
            raise ValueError("Missing required argument: {}".format(arg.name))

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_args = []
    for option in options_spec:
        if option.get("required_when"):
            condition = option["required_when"]
            if condition.get("command") == command_name:
                if condition.get("args"):
                    for arg in condition["args"]:
                        if arg in args:
                            required_args.append(option["name"])
                else:
                    required_args.append(option["name"])
    return required_args

def validate_length_args(self, args):
    for arg in args:
        if len(arg) > self.length:
            raise ValueError(f"Argument {arg} is longer than the specified length of {self.length}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if arg.choices is not None and arg.value not in arg.choices:
            msg = "Invalid choice: {0} is not one of {1}"
            raise ValueError(msg.format(arg.value, arg.choices))

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if len(args) < 2:
        raise ValueError("Expected at least 2 arguments, got %s" % len(args))
    if len(args) > 3:
        raise ValueError("Expected at most 3 arguments, got %s" % len(args))
    if args[0] > args[1]:
        raise ValueError("Minimum value must be less than or equal to maximum value")
    if len(args) == 3 and args[1] > args[2]:
        raise ValueError("Maximum value must be greater than or equal to minimum value")
    return args

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith("--"):
            control_args[arg] = args[arg]
        elif arg.startswith("-"):
            nested_args[arg] = args[arg]
        else:
            custom_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    for extra_var in extra_vars:
        if extra_var not in vars_dict:
            vars_dict[extra_var] = None
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if parser_name == "main":
        if "--port" in values_dict:
            values_dict["--port"] = int(values_dict["--port"])
        if "--host" in values_dict:
            values_dict["--host"] = str(values_dict["--host"])
        if "--blotter" in values_dict:
            values_dict["--blotter"] = str(values_dict["--blotter"])
        if "--nopass" in values_dict:
            values_dict["--nopass"] = bool(values_dict["--nopass"])
    elif parser_name == "virsh":
        if "--port" in values_dict:
            values_dict["--port"] = int(values_dict["--port"])
        if "--host" in values_dict:
            values_dict["--host"] = str(values_dict["--host"])
        if "--blotter" in values_dict:
            values_dict["--blotter"] = str(values_dict["--blotter"])
        if "--nopass" in values_dict:
            values_dict["--nopass"] = bool(values_dict["--nopass"])
    elif parser_name == "ospd":
        if "--port" in values_dict:
            values_dict["--port"] = int(values_dict["--port"])
        if "--host" in values_dict:
            values_dict["--host"] = str(values_dict["--host"])
        if "--blotter" in values_dict:
            values_dict["--blotter"] = str(values_dict["--blotter"])
        if "--nopass" in values_dict:
            values_dict["--nopass"] = bool(values_dict["--nopass"])
    else:
        raise ValueError("Invalid parser name")
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = get_plugin_spec(plugin_dir)
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                flatten_dict[f"{key}.{sub_key}"] = sub_value
        else:
            flatten_dict[key] = value
    return flatten_dict

def inject_config(self):
    if not os.environ.get('CONFIG_PATH'):
        os.environ['CONFIG_PATH'] = self.config_path
    return self.config_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
